Definition poison_cells (m : amem) : Prop :=
     rw_cells asegs m 0xaf718 [C8 (Z_to_bv 64 0x1494a8); C8 (Z_to_bv 64 0xb5178); C8 (Z_to_bv 64 0xb7978);
                               C8 (Z_to_bv 64 0xb8668); C8 (Z_to_bv 64 0xb8670); C8 (Z_to_bv 64 0xb8660)]
  /\ rw_cells asegs m 0xaf748 [C8 (Z_to_bv 64 0xb15a8)]
  /\ rw_cells asegs m 0xb15a0 [C8 (Z_to_bv 64 0xa8a58); C8 (Z_to_bv 64 0xa8e5c)]
  /\ rw_cells asegs m 0xb7978 [C8 (Z_to_bv 64 0x7fff8000)]
  /\ rw_cells asegs m 0xb8660 [C8 (Z_to_bv 64 0x7fffffffffff); C8 (Z_to_bv 64 0); C8 (Z_to_bv 64 0)]
  /\ rw_cells asegs m 0xb71dc [C1 (Z_to_bv 8 1)]
  /\ rw_cells asegs m 0x149520 [C8 (Z_to_bv 64 18446744073709551615)].   (* [comment removed for export] *)

Lemma poison_cells_frame : forall m m' W,
  poison_cells m -> munch W m m' -> wmono asegs m m' ->
  Forall (fun iv => AIMG_HI <= fst iv) W -> poison_cells m'.
